#!/usr/bin/env python3
"""Build the existing reader layout from the intact Iddhipada handoff."""
import argparse,json,subprocess
from pathlib import Path
from PIL import Image
ROOT=Path(__file__).resolve().parents[1];DOCS=ROOT/'docs/iddhipada'
def compile_book():
 subprocess.run(['python3',str(DOCS/'scripts/validate.py')],check=True)
 story=json.loads((DOCS/'storyboard.json').read_text());catalog=json.loads((DOCS/'scripture-catalog.json').read_text());layout=json.loads((DOCS/'overlay-layout.json').read_text())['overlays'];scenes=[];pages=[]
 for scene in story['scenes']:
  with Image.open(DOCS/scene['image']) as im:dimensions=list(im.size)
  scenes.append({'id':scene['sceneId'],'title':scene['title'],'image':scene['image'],'alt':scene['title'],'bakedText':scene['bakedText'],'dimensions':dimensions,'start':len(pages),'startSeconds':scene['startSeconds'],'endSeconds':scene['endSeconds'],'artOverlay':layout[scene['sceneId']],'summaryRows':[]})
  for n in scene['narration']:
   pages.append({'scene':scene['sceneId'],'title':scene['title'],'paragraphId':n['id'],'paragraphNumber':int(n['id'][1:]),'startSeconds':n['startSeconds'],'endSeconds':n['endSeconds'],'lines':[n['text']],'quotes':[dict(catalog[q],quoteId=q) for q in n['quoteIds']],'sourceNote':None,'context':None,'image':'../assets/'+scene['sceneId']+'.webp','dimensions':dimensions})
 assert len(pages)==81 and len(scenes)==9
 pages.append({'scene':'S09','title':'閱讀說明','lines':[],'quotes':[],'sourceNote':None,'context':None,'image':None,'dimensions':None,'afterword':True,'textSummary':[{'title':'經典依據','paragraphs':['本繪本依《相應部》第51相應的相關經文與《雜阿含經》第561經製作。口白中的划船、引擎與抵岸是故事譬喻，解讀仍請以原經文為準。','也希望這本繪本能成為您走入經藏的起點。'],'rows':[]} ]})
 return '// Generated by scripts/build-iddhipada.py; original handoff preserved.\nconst BOOK = '+json.dumps({'title':'四如意足','layout':'caption-art-scripture','timingAccuracy':story['timingAccuracy'],'video':story['video'],'scenes':scenes,'pages':pages},ensure_ascii=False,indent=2)+';\n'
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');args=p.parse_args();f=ROOT/'iddhipada/book/book-data.js';s=compile_book()
 if args.check:assert f.read_text()==s
 else:f.write_text(s)
 print('9 scenes / 81 unchanged timed paragraphs / 11 Q cards / 13 overlays / 82 pages including editorial ending')
